// Font analyzer (src/resources/font.ts) and the sfnt reader it uses. The fixtures are synthetic: generated by
// scripts/make-font-fixtures.py from box glyphs, so no third-party outlines are committed.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import * as wawoff2 from "wawoff2";
import { analyzer } from "../src/resources/font.js";
import { countRanges, detectFormat, inRanges, intersectRanges, mergeCodes, parseSfnt, toSfnt } from "../src/resources/sfnt.js";
import type { PageContext, ResourceRecord } from "../src/resources/types.js";

const fixture = (name: string): Buffer => readFileSync(join(__dirname, "fixtures", "fonts", name));

const LATIN_TEXT = "The quick brown fox jumps over the lazy dog. Sphinx of black quartz, judge my vow! 0123456789 ".repeat(4);

function ctx(over: Partial<PageContext> = {}): PageContext {
  return {
    url: "https://page.example.test/",
    viewport: { name: "desktop", width: 1440, height: 900, dpr: 1 },
    text: LATIN_TEXT,
    usedFonts: [{ family: "Synthetic Sans", weight: 400, style: "normal" }],
    fontFaces: [],
    icons: [],
    audio: [],
    lottie: [],
    models: [],
    ...over,
  };
}

function record(url: string, body: Buffer | undefined, over: Partial<ResourceRecord> = {}): ResourceRecord {
  return {
    url,
    pageUrl: "https://page.example.test/",
    viewport: "desktop",
    resourceType: "font",
    contentType: body && body.subarray(0, 4).toString("latin1") === "wOF2" ? "font/woff2" : "font/ttf",
    bytes: body?.length ?? 0,
    status: 200,
    thirdParty: false,
    body,
    ...over,
  };
}

describe("sfnt reader", () => {
  it("detects the container format from the first bytes", () => {
    expect(detectFormat(fixture("synthetic-sans-regular.ttf"))).toBe("sfnt");
    expect(detectFormat(fixture("synthetic-sans-regular.woff"))).toBe("woff");
    expect(detectFormat(fixture("synthetic-sans-regular.woff2"))).toBe("woff2");
    expect(detectFormat(Buffer.from("hello world, not a font"))).toBe("unknown");
  });

  it("reads glyph count, family, weight, cmap ranges and axes of a static font", () => {
    const info = parseSfnt(fixture("synthetic-sans-regular.ttf"));
    expect(info).not.toBeNull();
    expect(info!.families).toContain("Synthetic Sans");
    expect(info!.weightClass).toBe(400);
    expect(info!.axes).toEqual([]);
    expect(inRanges(info!.ranges, 0x41)).toBe(true); // A
    expect(inRanges(info!.ranges, 0x416)).toBe(true); // Cyrillic zhe
    expect(inRanges(info!.ranges, 0x2603)).toBe(false); // snowman: not in the font
    expect(info!.codepoints).toBeGreaterThan(400);
  });

  it("reads the wght axis of a variable font", () => {
    const info = parseSfnt(fixture("synthetic-sans-variable.ttf"));
    expect(info!.axes).toEqual([{ tag: "wght", min: 100, default: 400, max: 900 }]);
  });

  it("returns null for garbage and for a truncated table directory", () => {
    expect(parseSfnt(Buffer.from("not a font at all, just text"))).toBeNull();
    expect(parseSfnt(fixture("synthetic-sans-regular.ttf").subarray(0, 40))).toBeNull();
  });

  it("unwraps WOFF 1.0 and WOFF2 to sfnt bytes that parse to the same coverage", async () => {
    const direct = parseSfnt(fixture("synthetic-sans-regular.ttf"))!;
    const fromWoff = parseSfnt((await toSfnt(fixture("synthetic-sans-regular.woff"), "woff"))!);
    const fromWoff2 = parseSfnt((await toSfnt(fixture("synthetic-sans-regular.woff2"), "woff2"))!);
    expect(fromWoff!.codepoints).toBe(direct.codepoints);
    expect(fromWoff2!.codepoints).toBe(direct.codepoints);
    expect(fromWoff2!.families).toContain("Synthetic Sans");
  });

  it("returns null for an unsupported or malformed wrapper", async () => {
    expect(await toSfnt(Buffer.from("garbage"), "unknown")).toBeNull();
    expect(await toSfnt(Buffer.from("wOF2 not really"), "woff2")).toBeNull();
  });

  it("merges, intersects and counts ranges", () => {
    expect(mergeCodes([[5, 9], [1, 3], [4, 4], [20, 20]])).toEqual([[1, 9], [20, 20]]);
    expect(intersectRanges([[0, 10], [20, 30]], [[5, 25]])).toEqual([[5, 10], [20, 25]]);
    expect(countRanges([[0, 9], [20, 20]])).toBe(11);
  });
});

describe("font analyzer: wants", () => {
  it("wants font responses and nothing else", () => {
    expect(analyzer.wants(record("https://x.test/a.bin", undefined, { resourceType: "font" }))).toBe(true);
    expect(analyzer.wants(record("https://x.test/a.woff2", undefined, { resourceType: "other", contentType: "application/octet-stream" }))).toBe(true);
    expect(analyzer.wants(record("https://x.test/a.ttf", undefined, { resourceType: "other", contentType: "application/x-font-ttf" }))).toBe(true);
    expect(analyzer.wants(record("https://x.test/a.css", undefined, { resourceType: "stylesheet", contentType: "text/css" }))).toBe(false);
    expect(analyzer.wants(record("https://x.test/a.png", undefined, { resourceType: "image", contentType: "image/png" }))).toBe(false);
  });
});

describe("font analyzer: findings", () => {
  it("a TTF with a Latin-only page: WOFF2 and a subset are the savings, with real bytes and the pyftsubset line", async () => {
    const body = fixture("synthetic-sans-regular.ttf");
    const url = "https://page.example.test/fonts/Synthetic-Sans-Regular.ttf";
    const [f] = await analyzer.analyze([record(url, body)], ctx());
    expect(f).toBeDefined();
    expect(f.kind).toBe("font");
    expect(f.id).toMatch(/^font:[0-9a-f]{12}$/);
    expect(f.bytes).toBe(body.length);
    expect(f.savedBytes).toBeGreaterThan(body.length / 2);
    expect(f.estimate).toBe(false);
    expect(f.title).toContain("TTF");
    expect(f.title).toContain("WOFF2");
    expect(f.title).toContain("subset to the page's scripts");
    expect(f.fix.join("\n")).toContain("pyftsubset Synthetic-Sans-Regular.ttf --unicodes=U+0000-007F");
    expect(f.fix.join("\n")).toContain("--flavor=woff2");
    expect(f.fix.join("\n")).not.toContain("Cyrillic"); // the page has no Cyrillic text
  });

  it("the subset keeps the scripts the page text uses (Cyrillic here)", async () => {
    const body = fixture("synthetic-sans-regular.ttf");
    const cyrillic = "Съешь же ещё этих мягких французских булок да выпей чаю ".repeat(3);
    const [f] = await analyzer.analyze([record("https://page.example.test/a.ttf", body)], ctx({ text: cyrillic }));
    expect(f.fix.join("\n")).toContain("Cyrillic");
    expect(f.fix.join("\n")).toContain("U+0400-04FF");
  });

  it("an already WOFF2 font with the same coverage as the page needs gets no finding", async () => {
    const body = fixture("synthetic-sans-regular.woff2");
    const out = await analyzer.analyze([record("https://page.example.test/a.woff2", body)], ctx({ text: "" }));
    expect(out).toEqual([]);
  });

  it("an unused face (status unloaded, family not in the rendered text) is reported as wasted bytes", async () => {
    const body = fixture("synthetic-sans-regular.woff2");
    const url = "https://page.example.test/fonts/unused.woff2";
    const out = await analyzer.analyze(
      [record(url, body)],
      ctx({
        usedFonts: [{ family: "Other Family", weight: 400, style: "normal" }],
        fontFaces: [{ family: "Synthetic Sans", weight: "400", style: "normal", status: "unloaded", url }],
      }),
    );
    const unused = out.find((f) => f.title.includes("not used"));
    expect(unused).toBeDefined();
    expect(unused!.title).toContain("not used");
    expect(unused!.title).toContain("unloaded");
    expect(unused!.estimate).toBe(false);
  });

  it("a face the browser rendered with (status loaded) is never called unused", async () => {
    const body = fixture("synthetic-sans-regular.woff2");
    const url = "https://page.example.test/fonts/used.woff2";
    const out = await analyzer.analyze(
      [record(url, body)],
      ctx({
        usedFonts: [{ family: "Other Family", weight: 400, style: "normal" }],
        fontFaces: [{ family: "Synthetic Sans", weight: "400", style: "normal", status: "loaded", url }],
      }),
    );
    expect(out.some((f) => f.title.includes("not used"))).toBe(false);
  });

  it("a used family but a weight nobody renders is unused for that face", async () => {
    const body = fixture("synthetic-sans-light.ttf");
    const url = "https://page.example.test/fonts/light.ttf";
    const out = await analyzer.analyze(
      [record(url, body)],
      ctx({
        usedFonts: [{ family: "Synthetic Sans", weight: 700, style: "normal" }],
        fontFaces: [{ family: "Synthetic Sans", weight: "300", style: "normal", status: "unloaded", url }],
      }),
    );
    const unused = out.find((f) => f.title.includes("weight and style"));
    expect(unused).toBeDefined();
    expect(unused!.savedBytes).toBe(body.length);
  });

  it("an icon font (private-use code points) gets no subset and no unused claim", async () => {
    const body = fixture("synthetic-icons.ttf");
    const url = "https://page.example.test/fonts/icons.ttf";
    const out = await analyzer.analyze(
      [record(url, body)],
      ctx({
        usedFonts: [{ family: "Other", weight: 400, style: "normal" }],
        fontFaces: [{ family: "Synthetic Icons", weight: "400", style: "normal", status: "unloaded", url }],
      }),
    );
    // The WOFF2 conversion is still a real saving; the subset and unused claims are not made for an icon font.
    expect(out.every((f) => !f.title.includes("subset") && !f.title.includes("not used"))).toBe(true);
  });

  it("several static weights of one family are informational: one variable font would do", async () => {
    const urls = ["light", "regular", "bold"].map((w) => `https://page.example.test/fonts/sans-${w}.ttf`);
    const bodies = [fixture("synthetic-sans-light.ttf"), fixture("synthetic-sans-regular.ttf"), fixture("synthetic-sans-bold.ttf")];
    const out = await analyzer.analyze(
      urls.map((u, i) => record(u, bodies[i])),
      ctx({ text: "" }),
    );
    const family = out.find((f) => f.title.includes("could be one variable font"));
    expect(family).toBeDefined();
    expect(family!.savedBytes).toBe(0);
    expect(family!.title).toContain("3 static faces in 3 files");
    expect(family!.title).toContain("weights 300–700");
  });

  it("a variable font is not called a family of statics", async () => {
    const out = await analyzer.analyze([record("https://page.example.test/v.ttf", fixture("synthetic-sans-variable.ttf"))], ctx({ text: "" }));
    expect(out.some((f) => f.title.includes("could be one variable font"))).toBe(false);
  });

  it("a face the site already split by unicode-range is not offered a subset", async () => {
    const body = fixture("synthetic-sans-regular.ttf");
    const url = "https://page.example.test/fonts/slice.ttf";
    const out = await analyzer.analyze(
      [record(url, body)],
      ctx({ fontFaces: [{ family: "Synthetic Sans", weight: "400", style: "normal", status: "loaded", url, unicodeRange: "U+0000-00FF" }] }),
    );
    expect(out).toHaveLength(1);
    expect(out[0].fix.join("\n")).not.toContain("pyftsubset");
    expect(out[0].title).not.toContain("subset");
  });

  it("the same font bytes under two URLs: one font finding, and the second copy is reported as downloaded again", async () => {
    const body = fixture("synthetic-sans-regular.ttf");
    const out = await analyzer.analyze(
      [record("https://cdn.example.test/a.ttf", body), record("https://page.example.test/b.ttf", body)],
      ctx({ text: "" }),
    );
    const dup = out.find((f) => f.url.endsWith("/b.ttf"));
    expect(dup).toBeDefined();
    expect(dup!.savedBytes).toBe(body.length);
    expect(dup!.title).toContain("downloaded again");
    expect(out.filter((f) => f.url.endsWith("/a.ttf"))).toHaveLength(1);
  });

  it("a script slice with no face URL match is not offered a subset (it is already split)", async () => {
    const out = await analyzer.analyze(
      [record("https://page.example.test/slice.ttf", fixture("synthetic-slice-latin-ext.ttf"))],
      ctx(),
    );
    expect(out.every((f) => !f.fix.join("\n").includes("pyftsubset"))).toBe(true);
  });

  it("a saving under 10% of the file is not reported", async () => {
    // The WOFF2 of this font is already smaller than the file by well over 5%, so use the WOFF2 bytes: no saving.
    const out = await analyzer.analyze([record("https://page.example.test/x.woff2", fixture("synthetic-sans-regular.woff2"))], ctx({ text: "" }));
    expect(out).toEqual([]);
  });

  it("never throws: garbage, missing bodies and an empty list give no findings", async () => {
    expect(await analyzer.analyze([record("https://page.example.test/x.woff2", Buffer.from("junk junk junk junk"))], ctx())).toEqual([]);
    expect(await analyzer.analyze([record("https://page.example.test/x.woff2", undefined)], ctx())).toEqual([]);
    expect(await analyzer.analyze([], ctx())).toEqual([]);
  });

  it("the same URL in two viewports is analysed once", async () => {
    const body = fixture("synthetic-sans-regular.ttf");
    const url = "https://page.example.test/a.ttf";
    const out = await analyzer.analyze([record(url, body), record(url, body, { viewport: "mobile" })], ctx());
    expect(out.filter((f) => f.url === url)).toHaveLength(1);
  });

  it("the WOFF2 size it reports is the real wawoff2 output size", async () => {
    const body = fixture("synthetic-sans-regular.ttf");
    const real = (await wawoff2.compress(body)).length;
    const [f] = await analyzer.analyze([record("https://page.example.test/a.ttf", body)], ctx({ text: "" }));
    expect(f.details?.woff2Bytes).toBe(real);
    expect(f.savedBytes).toBe(body.length - real);
  });
});
